#include "game.hpp"
#include <algorithm>
#include <iostream>
#include <string>
namespace echodrive {
Game::Game():settings_(loadSettings("echodrive.cfg")),voice_(settings_.language){audio_.setListener({0,0,0},0);}
void Game::menu()const{std::cout<<"\n=== EchoDrive 0.4 | Ahmed Samy Studio ===\n1 تقدم | 2 فرامل | 3 يمين | 4 يسار | 5 أسرع | 6 أبطئ\na قيادة آلية | m قيادة يدوية | r إعادة | s الحالة | l الشوارع | v السيارات\nw الطقس التالي | t تقرير المرور | q خروج\n> ";}
void Game::selectStreet(){std::cout<<"اختر شارعًا من 1 إلى 15: ";int n=1;std::cin>>n;std::cin.ignore(10000,'\n');if(n<1||n>15)n=1;settings_.street=n;const auto&x=allStreets()[n-1];auto assets=assetsForStreet(n);runtime_.setListener({0,0,0},0);runtime_.playLoop(assets.ambience,{0,0,8},0.45f);traffic_.reset(n);voice_.announce("بدأت "+x.ar+" من دولة "+x.country+". "+x.description,"Starting "+x.en+" in "+x.country+". "+x.description);}
void Game::selectVehicle(){std::cout<<"اختر سيارة من 1 إلى 25: ";int n=1;std::cin>>n;std::cin.ignore(10000,'\n');if(n<1||n>25)n=1;vehicle_=n;auto assets=assetsForStreet(settings_.street);runtime_.playLoop(assets.engine,{0,0,1},0.70f);const auto&x=allVehicles()[n-1];voice_.announce("اخترت "+x.ar+"، السرعة القصوى "+std::to_string(x.topSpeed),"Selected "+x.en+", top speed "+std::to_string(x.topSpeed));}
Command Game::parse(const std::string&r)const{if(r=="1"||r=="forward"||r=="تقدم")return Command::Forward;if(r=="2"||r=="توقف"||r=="فرامل")return Command::Brake;if(r=="3"||r=="right"||r=="يمين")return Command::Right;if(r=="4"||r=="left"||r=="يسار")return Command::Left;if(r=="5"||r=="أسرع")return Command::Faster;if(r=="6"||r=="أبطئ")return Command::Slower;if(r=="a"||r=="قيادة آلية")return Command::Auto;if(r=="m"||r=="قيادة يدوية")return Command::Manual;if(r=="r"||r=="إعادة")return Command::Reset;if(r=="s")return Command::Repeat;if(r=="l")return Command::ListStreets;if(r=="v")return Command::ListVehicles;if(r=="w"||r=="طقس")return Command::WeatherCycle;if(r=="t"||r=="مرور")return Command::Traffic;if(r=="q"||r=="خروج")return Command::Quit;return Command::Unknown;}
void Game::status()const{std::string d=heading_<0?"يسار":heading_>0?"يمين":"مستقيم";std::string e=heading_<0?"left":heading_>0?"right":"straight";const auto&car=allVehicles()[vehicle_-1];const auto&ws=weather_.state();voice_.announce("السرعة "+std::to_string((int)speed_)+" كيلومتر، الاتجاه "+d+"، السيارة "+car.ar+"، الطقس "+weather_.name(true)+"، الحرارة "+std::to_string(ws.temperature)+"، الرطوبة "+std::to_string(ws.humidity)+" بالمئة","Speed "+std::to_string((int)speed_)+" kilometers per hour, direction "+e+", vehicle "+car.en+", weather "+weather_.name(false)+", temperature "+std::to_string(ws.temperature)+", humidity "+std::to_string(ws.humidity)+" percent");}
void Game::listContent()const{std::cout<<"\n--- 15 Streets ---\n";for(const auto&s:allStreets())std::cout<<s.id<<". "<<s.en<<" — "<<s.country<<"\n";std::cout<<"\n--- 25 Vehicles ---\n";for(const auto&v:allVehicles())std::cout<<v.id<<". "<<v.en<<" ["<<v.category<<"] max "<<v.topSpeed<<" km/h\n";}
void Game::handle(Command c){switch(c){case Command::Forward:speed_=std::min((double)allVehicles()[vehicle_-1].topSpeed,speed_+8);traffic_.tick(speed_,settings_.automaticDriving);voice_.announce("تقدم. "+traffic_.nearestAlert(true),"Moving forward. "+traffic_.nearestAlert(false));break;case Command::Brake:speed_=std::max(0.0,speed_-20);traffic_.tick(speed_,settings_.automaticDriving);voice_.announce("فرامل","Braking");break;case Command::Right:heading_=1;audio_.setListener({0,0,0},0.25);voice_.announce("يمين، الصوت الآن من الجهة اليمنى","Turning right, audio cue on the right");break;case Command::Left:heading_=-1;audio_.setListener({0,0,0},-0.25);voice_.announce("يسار، الصوت الآن من الجهة اليسرى","Turning left, audio cue on the left");break;case Command::Faster:speed_=std::min((double)allVehicles()[vehicle_-1].topSpeed,speed_+15);traffic_.tick(speed_,settings_.automaticDriving);status();break;case Command::Slower:speed_=std::max(0.0,speed_-15);traffic_.tick(speed_,settings_.automaticDriving);status();break;case Command::Auto:settings_.automaticDriving=true;voice_.announce("تم تشغيل القيادة الآلية، سأراقب حركة المرور","Automatic driving enabled, monitoring traffic");break;case Command::Manual:settings_.automaticDriving=false;voice_.announce("تم تشغيل القيادة اليدوية","Manual driving enabled");break;case Command::Reset:speed_=0;heading_=0;audio_.setListener({0,0,0},0);traffic_.reset(settings_.street);weather_.set(Weather::Clear);voice_.announce("أعيدت الرحلة والطقس إلى الصحو","Trip and weather reset to clear");break;case Command::Repeat:status();break;case Command::ListStreets:case Command::ListVehicles:listContent();break;case Command::WeatherCycle:{weather_.cycle();runtime_.playLoop(weather_.ambiencePath(),{0,0,5},0.38f);voice_.announce("الطقس الآن "+weather_.name(true)+". "+weather_.advisory(true),"Weather is now "+weather_.name(false)+". "+weather_.advisory(false));break;}case Command::Traffic:traffic_.tick(speed_,settings_.automaticDriving);voice_.announce(traffic_.nearestAlert(true),traffic_.nearestAlert(false));break;case Command::Quit:saveSettings(settings_,"echodrive.cfg");voice_.announce("إلى اللقاء","Goodbye");break;case Command::Unknown:voice_.announce("لم أفهم الأمر","Command not understood");}}
void Game::run(){voice_.announce("مرحبًا بك في EchoDrive. المرور والطقس والصوت المكاني مفعلة.","Welcome to EchoDrive. Traffic, weather and spatial audio are enabled.");selectStreet();selectVehicle();for(;;){menu();std::string x;if(!std::getline(std::cin,x))break;Command c=parse(x);handle(c);if(c==Command::Quit)break;}}
}
